              "tafseer": "قد كان في أول الأمر يحرم على الرجل إذا نام في ليلة الصيام ثم استيقظ قبل الفجر أن يأكل أو يقرب أهله، فنسخ الله ذلك، وأباح الله لكم -أيها المؤمنون- في ليالي الصيام جماع نسائكم، فهن ستر وإعفاف لكم، وأنتم ستر وإعفاف لهن، لا يستغني بعضكم عن بعض، عَلِمَ الله أنكم كنتم تخانون أنفسكم بفعل ما نهاكم عنه، فرحمكم وتاب عليكم، وخفف عنكم، فالآن جامعوهن، واطلبوا ما قدَّر الله لكم من الذرية، وكلوا واشربوا في الليل كله، حتى يتبين لكم طلوع الفجر الصادق ببياض الفجر وانفصاله عن سواد الليل، ثم أكملوا الصيام بالإمساك عن المفطرات من طلوع الفجر حتى تغيب الشمس، ولا تجامعوا النساء وأنتم معتكفون في المساجد؛ لأن ذلك يبطله. تلك الأحكام المذكورة هي حدود الله بين الحلال والحرام فلا تقربوها أبدًا؛ فإن من اقترب من حدود الله يوشك أن يقع في الحرام، وبمثل هذا البيان الواضح الجلي لتلك الأحكام يبين الله آياته للناس لعلهم يتقونه بفعل ما أمر وثبت ما نهى."
