              "tafseer": "وأدوا الحج والعمرة تامَّين، مبتغين وجه الله تعالى، فإذا مُنِعْتُم من إتمامهما بمرض أو عدوّ أو نحو ذلك؛ فعليكم ذبح ما تيسر من الهدي - من الإبل أو البقر أو الغنم - لتتحللوا من إحرامكم. ولا تحلقوا رؤوسكم أو تقصروها حتى يبلغ الهدي الموضع الذي يحِلُّ فيه ذبحه، فإن كان ممنوعًا من الحرم فليذبح حيث مُنِع، وإن كان غير ممنوع من الحرم فليذبح في الحرم يوم النحر وما بعده من أيام التشريق. فمن كان منكم مريضًا، أو به أذى من شعر رأسه؛ كقمل ونحوه، فَحَلَقَ رأسه بسبب ذلك، فلا حرج عليه، وعليه أن يفدي عن ذلك؛ إما بصيام ثلاثة أيام، أو بإطعام ستة مساكين من مساكين الحرم، أو بذبح شاة توزع على فقراء الحرم. فإذا كنتم غير خائفين فمن استمتع منكم بأداء العمرة في أشهر الحج، وتمتع بما حَرُمَ عليه من محظورات الإحرام إلى أن يحرم بالحج من عامه؛ فليذبح ما تيسر له من شاة أو يشترك سبعة في ذبح بعير أو بقرة، فإذا لم يقدر على الهدي فعليه صيام ثلاثة أيام من أيام المناسك بدلاً منه، وعليه صيام سبعة أيام بعد رجوعه إلى أهله، ليكون مجموع الأيام عشرة كاملة. ذلك التمتع مع وجوب الهدي أو الصيام للعاجز عن الهدي هو لغير أهل الحرم ومن يقيم قريبًا من الحرم، واتقوا الله باتباع ما شرع، وتعظيم حدوده، واعلموا أن الله شديد العقاب لمن خالف أمره."
