              "tafseer": "ويسألك أصحابك - أيها النبي - عن الحيض (وهو دم طبيعي يخرج من رحم المرأة في أوقات مخصوصة)؟ قل مجيبًا إياهم: الحيض أذى للرجل والمرأة، فاجتنبوا جماع النساء في وقته، ولا تقربوهن بالوطء حتى ينقطع الدم عنهن، ويتطهرن منه بالغُسل، فإذا انقطع وتطهرن منه فجامعوهن على الوجه الذي أباح لكم: طاهرات في قُبُلهن، إن الله يحب المكثرين من التوبة من المعاصي، والمبالغين في الطهارة من الأخباث."
